   195→        let mut meta_data_quota = None;
   196→        let mut status_quota = None;
   197→        let mut goodbye_quota = None;
   198→        let mut blocks_by_range_quota = None;
   199→        let mut blocks_by_root_quota = None;
   200→        let mut blobs_by_range_quota = None;
